import time
from functools import wraps

API_KEYS = {'demo': 'secret123', 'alpha': 'key-alpha'}
REQUEST_LOG = {}

def require_key(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        key = request.headers.get('X-API-Key')
        if key not in API_KEYS:
            return jsonify({'error': 'Unauthorized'}), 401
        now = time.time()
        window = REQUEST_LOG.setdefault(key, [])
        window[:] = [t for t in window if now - t < 60]
        if len(window) >= 10:
            return jsonify({'error': 'Too many requests'}), 429
        window.append(now)
        return f(*args, **kwargs)
    return decorated

@app.route('/scrape')
@require_key
def scrape():
    url = request.args.get('url')
    if not url:
        return jsonify({'error': 'url parameter is required'}), 400
    try:
        scraper = WebScraper(url)
        html = asyncio.run(scraper.fetch())
        soup = BeautifulSoup(html, 'html.parser')
        headings = [tag.get_text(strip=True) for tag in soup.find_all(['h1', 'h2', 'h3', 'h4', 'h5', 'h6'])]
        return jsonify({'headings': headings})
    except ValueError as ve:
        return jsonify({'error': str(ve)}), 400
    except RuntimeError as re:
        return jsonify({'error': str(re)}), 500
